import pandas as pd, numpy as np, glob
from scipy.optimize import least_squares
files=['train/A3_amb_op1.csv','train/A3_amb_op2.csv','train/A3_vref_op1.csv','train/A3_vref_op3.csv','train/A3_gentrip_op1.csv','train/A3_load_op2.csv','train/A3_line_op3.csv']
D=[]
for f in files:
    d=pd.read_csv(f)
    D.append(dict(t=d.time_s.values,V=d.voltage_pu.values,Q=d.reactive_power_pu.values,S=d.voltage_setpoint_pu.values,V0=d.voltage_pu.values[0],Q0=d.reactive_power_pu.values[0],S0=d.voltage_setpoint_pu.values[0]))
def simQ(p,d,dt=0.001):
    kV,kS,TQ=p
    V=d['V'];S=d['S'];n=len(V)
    Qm=d['Q0']; out=np.empty(n); out[0]=Qm
    for k in range(1,n):
        Qe=d['Q0']+kV*(V[k-1]-d['V0'])+kS*(S[k-1]-d['S0'])
        Qm+=dt*(Qe-Qm)/TQ
        out[k]=Qm
    return out
def res(p):
    return np.concatenate([simQ(p,d)-d['Q'] for d in D])
for p0 in [[-1,0,0.05],[-10,0,0.5],[-0.1,0.1,0.01]]:
    s=least_squares(res,p0,bounds=([-50,-50,0.001],[50,50,5]))
    print(s.x.round(4), np.std(s.fun).round(5))
    for d,f in zip(D,files):
        print('  ',f, np.std(simQ(s.x,d)-d['Q']).round(5))

import json, numpy as np
XL,mp,TPf=0.32440703,0.05881391,0.00750138
kV,TQ=-0.0037,0.0619
sub={
 "params":{"XL":XL,"mp":mp,"TPf":TPf,"w0":2*np.pi*60,"kV":kV,"TQ":TQ},
 "defs":{
   "Eint":"sqrt((Q0*XL+V0**2)**2+(P0*XL)**2)/V0",
   "Pe":"V*Eint*sin(dl-theta)/XL"
 },
 "states":{
   "dl":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+atan2(P0*XL,Q0*XL+V0**2)"},
   "Pm":{"rhs":"(Pe-Pm)/TPf","init":"P0"},
   "Qs":{"rhs":"(Q0+kV*(V-V0)-Qs)/TQ","init":"Q0"}
 },
 "outputs":{"P":"Pe","Q":"Qs"}
}
json.dump(sub,open('submission.json','w'),indent=1)
